parameters.jsCode:
const b = $('Recebe pedido do app').first().json.body || {};
const texto = (v) => String(v == null ? "" : v).trim();
const lista = (v) => texto(v) || null;
const numero = (v) => {
  const n = Number(String(v == null ? "" : v).replace(",", "."));
  return Number.isFinite(n) ? n : 0;
};
const ehRegistro = (v) => /^rec[A-Za-z0-9]{14}$/.test(texto(v));
// [^0-9] em vez do atalho com barra invertida: escapar barra dentro de tanta
// camada de texto ja quebrou este arquivo uma vez.
const soDigitos = (v) => texto(v).replace(/[^0-9]/g, "");

// Quem manda no id e o n8n, nao o app. O app so diz O QUE mudar; ONDE
// gravar sai da busca aqui do lado. Assim um pedido malformado nao tem como
// criar uma segunda linha "principal" numa tabela que so aceita uma.
const achadas = $input.all().map((i) => i.json).filter((j) => j && j.id);
// A mais antiga e a de verdade: se um dia sobrar duplicata, a original ganha.
achadas.sort((x, y) => String(x.createdTime).localeCompare(String(y.createdTime)));
const id = achadas.length ? achadas[0].id : "";

// SO grava o que o pedido REALMENTE trouxe. Ja aconteceu de um script de
// teste mandar meia duzia de campos e zerar todo o resto da configuracao
// do dono, sem volta. Campo ausente no pedido agora fica como esta.
const veio = (chave) => Object.prototype.hasOwnProperty.call(b, chave);
const so = (chave, valor) => (veio(chave) ? { [nomeNoAirtable[chave]]: valor } : {});

const nomeNoAirtable = {
  saldoInicial: "Saldo_Inicial",
  dataSaldoInicial: "Data_Saldo_Inicial",
  reservaMeta: "Reserva_Meta",
  giroMeta: "Giro_Meta",
  regime: "Regime",
  impostoFixoMensal: "Imposto_Fixo_Mensal",
  aliquotaImposto: "Aliquota_Imposto",
  tetoAnual: "Teto_Anual",
  folhaMensal: "Folha_Mensal",
  provisionaDecimoFerias: "Provisiona_Decimo_Ferias",
  socio1Nome: "Socio_1_Nome",
  socio2Nome: "Socio_2_Nome",
  socio1Percentual: "Socio_1_Percentual",
  socio2Percentual: "Socio_2_Percentual",
};

const fields = {
  Chave: "principal",
  ...so("saldoInicial", numero(b.saldoInicial)),
  ...so("dataSaldoInicial", lista(b.dataSaldoInicial)),
  ...so("reservaMeta", numero(b.reservaMeta)),
  ...so("giroMeta", numero(b.giroMeta)),
  ...so("regime", lista(b.regime) || "MEI"),
  ...so("impostoFixoMensal", numero(b.impostoFixoMensal)),
  ...so("aliquotaImposto", numero(b.aliquotaImposto) / 100),
  ...so("tetoAnual", numero(b.tetoAnual)),
  ...so("folhaMensal", numero(b.folhaMensal)),
  ...so("provisionaDecimoFerias", texto(b.provisionaDecimoFerias) === "sim"),
  ...so("socio1Nome", texto(b.socio1Nome)),
  ...so("socio2Nome", texto(b.socio2Nome)),
  ...so("socio1Percentual", numero(b.socio1Percentual) / 100),
  ...so("socio2Percentual", numero(b.socio2Percentual) / 100),
};

return [{
  json: {
    invalido: false,
    metodo: ehRegistro(id) ? "PATCH" : "POST",
    url: "https://api.airtable.com/v0/appjAmWXV7Zr33UqE/tbl3uT9h7ZYXnfR7E",
    corpo: { typecast: true, records: [ehRegistro(id) ? { id, fields } : { fields }] },
  },
}];
